import Foundation

let cal = Calendar(identifier: .gregorian)
let from = cal.startOfDay(for: DateComponents(year: 2000, month: 5, day: 1).date!)
let until = cal.date(byAdding: .month, value: 1, to: from)!
let deadline = cal.date(byAdding: .second, value: -1, to: until)!   // closed end

struct Effectivity {                       // DateInterval is closed: [start, end]
    let window: DateInterval
    func contains(_ asOf: Date) -> Bool { window.contains(asOf) }
}

let cal = Calendar.current
func isEffective(on asOf: Date, from: DateComponents, until: DateComponents?) -> Bool {
    guard let start = cal.date(from: from) else { return false }
    if cal.compare(asOf, to: start, toGranularity: .day) == .orderedAscending { return false }
    guard let u = until, let end = cal.date(from: u) else { return true }   // open end
    return cal.compare(asOf, to: end, toGranularity: .day) == .orderedAscending  // half-open
}
